 "content": "from collections import Counter


def transform(grid):
    """Fill zero-masked portions of a diagonal-echo periodic field."""
    h, w = len(grid), len(grid[0])
    base = []
    for c in range(w):
        # Row 0 is the offset header; on the diagonal rows the previous
        # sequence value is echoed instead of the underlying column value.
        values = [grid[r][c] for r in range(1, h)
                  if r != c and grid[r][c] != 0]
        if not values:
            values = [grid[r][c] for r in range(1, h)
                      if grid[r][c] != 0]
        if not values:
            raise ValueError(f"cannot infer field value for column {c}")
        base.append(Counter(values).most_common(1)[0][0])

    out = []
    for r in range(h):
        if r == 0:
            out.append([grid[0][0]] + base[:w - 1])
        else:
            out.append([base[c - 1] if c == r and c > 0 else base[c]
                        for c in range(w)])
    return out


if __name__ == '__main__':
    import json
    import sys
    result = transform(json.load(sys.stdin))
    assert 1 <= len(result) <= 30 and all(len(row) == len(result[0]) for row in result)
    assert all(type(v) is int and 0 <= v <= 9 for row in result for v in row)
    print(json.dumps(result, separators=(',', ':')))
