    # region, where row progression and diagonal echoes expose each phase.
    template = [0] * w
    for c in range(w):
        samples = [grid[r][c] for r in range(h) if grid[r][c] != 0 and r != c]
        if samples:
            # The horizontal run is periodic; use the most frequent observed
            # non-diagonal value for its column.
            template[c] = max(set(samples), key=samples.count)
    # Complete any completely masked template positions from the cyclic order.
    for c in range(w):
        if not template[c]:
            if c and template[c - 1]:
