 "content": "def transform(grid):
    """Complete the cyclic field while preserving its diagonal repeated-step clue.

    Rows 1 onward contain a cyclic ascending sequence through 1..max_color,
    with the main-diagonal cell repeating the prior sequence value. Row 0 is
    the one-position-back header. Zeros are erased cells; retain all clues.
    """
    h, w = len(grid), len(grid[0])
    period = max(max(row) for row in grid)
    if h < 2 or period < 1:
        raise ValueError("grid lacks sequence clues")
    start = grid[1][0]

    def base(c):
        return ((start - 1 + c) % period) + 1

    output = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if output[r][c] == 0:
                if r == c and c > 0:
                    output[r][c] = base(c - 1)
                elif r == 0 and c == 0:
                    output[r][c] = base(w - 1)
                else:
                    output[r][c] = base(c)
    return output


if __name__ == '__main__':
